using System;
enum RebirthMetabolismSourceKind {HeldToolbelt,Backpack,HydrationSlot}
class ItemValue {public int type=1;public string Metadata="original",Texture="full-native-texture";public ItemValue Clone(){return (ItemValue)MemberwiseClone();}public bool Equals(ItemValue b){return b!=null&&type==b.type&&Metadata==b.Metadata;}}
class ItemStack {public ItemValue itemValue=new ItemValue();public int count=3;public static ItemStack Empty=new ItemStack {count=0};public bool IsEmpty(){return count<=0;}public ItemStack Clone(){return new ItemStack {count=count,itemValue=itemValue.Clone()};}}
class Slots {public Slots ItemGrid=>this;public ItemStack[] items=>Items;public bool IgnoreWrites;public bool AlterWrite;public Action AfterWrite;public ItemStack[] Items={new ItemStack(),new ItemStack()};public int Writes;public ItemStack[] GetSlots(){return Items;}public void SetSlot(int i,ItemStack s){if(AlterWrite){s.count++;s.itemValue.Metadata="setter-change";}if(!IgnoreWrites)Items[i]=s;Writes++;AfterWrite?.Invoke();}public void SetItem(int i,ItemStack s){SetSlot(i,s);}}
class WorldState{public string Guid="world";}
class World{public WorldState worldState=new WorldState();public bool Remote;public System.Collections.Generic.Dictionary<int,EntityPlayer> Actors=new System.Collections.Generic.Dictionary<int,EntityPlayer>();public bool IsRemote()=>Remote;public object GetEntity(int id)=>Actors.TryGetValue(id,out var actor)?actor:null;public void Bind(EntityPlayer p){p.world=this;Actors[p.entityId]=p;}}
class GameManager{public static GameManager Instance=new GameManager();public World World;}
static class ThreadManager{public static bool Main=true;public static bool IsMainThread()=>Main;}
class EntityPlayer {private static int ids;public int entityId=++ids,Died;public bool Dead;public string Creation="creation";public World world;public bool IsDead()=>Dead;public Slots bag=new Slots(),inventory=new Slots();}
class EntityPlayerLocal:EntityPlayer {}
static class RebirthHydrationOwnerHold {public static bool Held;public static bool HoldsMetabolismOwner(EntityPlayerLocal player)=>player!=null&&Held;}
static class RebirthHydrationServerSourceHold {public static bool Held;public static bool HoldsPlayer(EntityPlayer player)=>player!=null&&Held;}
class RebirthMetabolismState {public ItemStack HydrationSlotItem=new ItemStack();}
static class RebirthMetabolismStateRepository{public static System.Collections.Generic.Dictionary<EntityPlayer,RebirthMetabolismState> States=new System.Collections.Generic.Dictionary<EntityPlayer,RebirthMetabolismState>();public static bool TryGet(EntityPlayer p,out RebirthMetabolismState state)=>States.TryGetValue(p,out state);}
static class RebirthConsumptionOwnerPublication{public static bool TryCaptureCreation(EntityPlayer p,out string creation){creation=p.Creation;return creation!=null;}}
static class RebirthStationGridIngredients{public static bool IsSameStackSnapshot(ItemStack a,ItemStack b)=>a!=null&&b!=null&&a.count==b.count&&a.itemValue.type==b.itemValue.type&&a.itemValue.Metadata==b.itemValue.Metadata&&a.itemValue.Texture==b.itemValue.Texture;}
static class RebirthVehicleInventoryWrite{public static ItemStack[] Snapshot(ItemStack[] slots){var result=new ItemStack[slots.Length];for(int i=0;i<slots.Length;i++)result[i]=slots[i].Clone();return result;}public static bool SameSlots(ItemStack[] a,ItemStack[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(!RebirthStationGridIngredients.IsSameStackSnapshot(a[i],b[i]))return false;return true;}}
static class RebirthConsumptionTrace{public static void Note(string name,EntityPlayer player=null,RebirthMetabolismSourceKind kind=default(RebirthMetabolismSourceKind),int slot=-1,ItemStack before=null,ItemStack after=null,string reason=null,bool? success=null){}}
static class RebirthToolbeltCapacity {public static int GetOwnedSlotCount(EntityPlayer p,int length){return length-1;}}
static class RebirthBackpackLibraryReservation {public static bool Held;public static bool BlocksResourceUse(EntityPlayer p){return Held;}}
class Check {static void Assert(bool b,string m){if(!b)throw new Exception(m);}static void Main(){var p=new EntityPlayer();var s=new RebirthMetabolismState();var world=new World();world.Bind(p);GameManager.Instance.World=world;RebirthMetabolismStateRepository.States[p]=s;var expected=p.bag.Items[0].Clone();var replacement=expected.Clone();replacement.count=2;
 p.bag.Items[0].itemValue.Metadata="different";Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s)&&p.bag.Writes==0,"metadata conflict overwritten");p.bag.Items[0]=expected.Clone();p.bag.Items[0].count=4;Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s),"count conflict overwritten");p.bag.Items[0]=expected.Clone();Assert(RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s)&&p.bag.Items[0].count==2,"matching bag failed");replacement.itemValue.Metadata="later";Assert(p.bag.Items[0].itemValue.Metadata=="original","replacement alias");
 Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HeldToolbelt,1,expected,replacement,s)&&p.inventory.Writes==0,"dummy belt accepted");Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,(RebirthMetabolismSourceKind)99,0,expected,replacement,s)&&p.inventory.Writes==0,"unknown source fell through");Assert(RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HeldToolbelt,0,expected,null,s)&&p.inventory.Items[0].IsEmpty(),"belt clear failed");Assert(RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HydrationSlot,-1,expected,replacement,s)&&s.HydrationSlotItem.count==2,"hydration write failed");Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,-1,expected,replacement,s),"invalid index accepted"); p.bag.Items[0]=expected.Clone();p.bag.IgnoreWrites=true;Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s)&&p.bag.Items[0].count==3,"ignored bag setter acknowledged");
 p.inventory.Items[0]=expected.Clone();p.inventory.IgnoreWrites=true;Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HeldToolbelt,0,expected,replacement,s),"ignored belt setter acknowledged");
 RebirthBackpackLibraryReservation.Held=true;int writes=p.bag.Writes;Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s)&&p.bag.Writes==writes,"held source setter reached");s.HydrationSlotItem=expected.Clone();Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HydrationSlot,-1,expected,replacement,s)&&s.HydrationSlotItem.count==3,"held hydration source changed");
 RebirthBackpackLibraryReservation.Held=false;p.bag.IgnoreWrites=false;p.bag.AlterWrite=true;p.bag.Items[0]=expected.Clone();Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.Backpack,0,expected,replacement,s),"setter input mutation validated itself");
 var local=new EntityPlayerLocal();world.Bind(local);RebirthMetabolismStateRepository.States[local]=s;s.HydrationSlotItem=expected.Clone();RebirthHydrationOwnerHold.Held=true;
 Assert(!RebirthConsumptionSourceWriteback.TryCommit(local,RebirthMetabolismSourceKind.HydrationSlot,-1,expected,replacement,s)&&s.HydrationSlotItem.count==3,"hydration transfer hold consumed retained source");
 RebirthHydrationOwnerHold.Held=false;Assert(RebirthConsumptionSourceWriteback.TryCommit(local,RebirthMetabolismSourceKind.HydrationSlot,-1,expected,replacement,s),"unheld hydration source remained blocked");
 s.HydrationSlotItem=expected.Clone();RebirthHydrationServerSourceHold.Held=true;Assert(!RebirthConsumptionSourceWriteback.TryCommit(p,RebirthMetabolismSourceKind.HydrationSlot,-1,expected,replacement,s)&&s.HydrationSlotItem.count==3,"remote server hydration custody consumed retained source");
 RebirthHydrationServerSourceHold.Held=false;ScopeCases();
 Console.WriteLine("PASS: actual consumption source commit scope/full native images and existing writeback vectors; native identity/item codec/storage are adapters, durability NOT_RUN.");}
 static void ScopeCases(){
  for(int variant=0;variant<12;variant++){
   ThreadManager.Main=true;var world=new World();var player=new EntityPlayer();world.Bind(player);GameManager.Instance.World=world;var state=new RebirthMetabolismState();RebirthMetabolismStateRepository.States[player]=state;
   var before=player.bag.Items[0].Clone();var after=before.Clone();after.count--;
   player.bag.AfterWrite=()=>{switch(variant){case 0:player.Died++;break;case 1:player.Creation="other";break;case 2:GameManager.Instance.World=new World();break;case 3:RebirthMetabolismStateRepository.States[player]=new RebirthMetabolismState();break;case 4:player.bag.Items=new ItemStack[0];break;case 5:player.inventory.Items[1].itemValue.Metadata="unrelated";break;case 6:player.bag.Items[0].itemValue.Texture="lost-native-texture";break;case 7:player.bag=new Slots();break;case 8:world.worldState.Guid="other";break;case 9:world.worldState=new WorldState();break;case 10:world.Actors[player.entityId]=new EntityPlayer();break;case 11:ThreadManager.Main=false;break;}};
   Assert(!RebirthConsumptionSourceWriteback.TryCommit(player,RebirthMetabolismSourceKind.Backpack,0,before,after,state),"post-setter scope/full image drift acknowledged "+variant);
  }
  ThreadManager.Main=true;var validWorld=new World();var valid=new EntityPlayer();validWorld.Bind(valid);GameManager.Instance.World=validWorld;var current=new RebirthMetabolismState();RebirthMetabolismStateRepository.States[valid]=current;
  var expected=valid.bag.Items[0].Clone();var changed=expected.Clone();changed.count--;valid.bag.Items[0].itemValue.Texture="other";
  Assert(!RebirthConsumptionSourceWriteback.TryCommit(valid,RebirthMetabolismSourceKind.Backpack,0,expected,changed,current)&&valid.bag.Writes==0,"native texture-only source change admitted");
  valid.bag.Items[0]=expected.Clone();ThreadManager.Main=false;Assert(!RebirthConsumptionSourceWriteback.TryCommit(valid,RebirthMetabolismSourceKind.Backpack,0,expected,changed,current)&&valid.bag.Writes==0,"off-thread source setter reached");ThreadManager.Main=true;
  changed.count=expected.count+1;Assert(!RebirthConsumptionSourceWriteback.TryCommit(valid,RebirthMetabolismSourceKind.Backpack,0,expected,changed,current)&&valid.bag.Writes==0,"consumption source quantity increased");
 }
}
